#!/usr/bin/env python3
"""
Daily Maya Journal Entry Generator
This script generates a new journal entry for Maya Watson and adds it to journal.html
"""
import os
import sys
import subprocess
import re
from datetime import datetime

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
JOURNAL_PATH = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "journal.html")

def get_today_date():
    """Get today's date in format 'Month DD, YYYY'"""
    return datetime.now().strftime("%B %d, %Y")

def get_git_user():
    """Get git user config for commits"""
    return "github-actions[bot]", "github-actions[bot]@users.noreply.github.com"

def run_git_command(cmd, cwd=None):
    """Run a git command and return result"""
    result = subprocess.run(cmd, shell=True, cwd=cwd, capture_output=True, text=True)
    if result.returncode != 0:
        print(f"Command failed: {cmd}")
        print(f"stdout: {result.stdout}")
        print(f"stderr: {result.stderr}")
    return result

